// Transcribed from https://thronesdb.com/rulesreference — the official AGoT 2e
// Rules Reference (Introduction, Golden Rules, glossary, Appendix I, Component
// List), as re-hosted by the ThronesDB community site. Per that page's own
// footer: "information presented ... about A Game of Thrones: The Card Game
// Second Edition ... is copyrighted by Fantasy Flight Games." Reproduced here
// for the same non-commercial fan purpose as the rest of this project's card
// data. A handful of source elements couldn't be carried over as-is and were
// adapted: icon glyphs (e.g. military/intrigue/power) became bracket text
// matching this app's existing card-text convention, and the image-only
// "Timing Sequence Chart" flowchart (no page hosting those images here) was
// replaced with a pointer to the equivalent step-by-step text below it.
// Update by re-fetching that page and re-transcribing the changed entries if
// the Rules Reference is ever revised upstream — a data edit, not a code
// change.
export interface RulesReferenceEntry {
  slug: string;
  term: string;
  letter: string;
  html: string;
}

export const RULES_REFERENCE_INTRODUCTION: { title: string; html: string } = {
  title: "The Only Game That Matters",
  html: "<blockquote><em>Too many strange faces, Tyrion thought, too many new players. The game changed while I lay rotting\n in my bed, and no one will tell me the rules.</em><br>\n \u2014 <cite>George R.R. Martin, <em>A Song of Ice and Fire</em></cite></blockquote>\n <p>This document is intended as the definitive source for rules information, but does not teach players how to play\n the game. Players should first read the Learn to Play book in its entirety and use this Rules Reference as\n needed while playing the game.</p>\n <p>The majority of this guide consists of the glossary, which provides an alphabetical listing of terms and\n situations a player might encounter during a game. This section should be the first destination for players who\n have a rules question.</p>\n <p>The latter part of this guide contains two appendices. The first appendix provides detailed timing diagrams that\n illustrate the structure of an entire game round, as well as a detailed explanation on how to handle each game\n step presented in those diagrams. The second provides a detailed anatomy of each cardtype.</p>",
};

export const RULES_REFERENCE_GOLDEN_RULES: { title: string; html: string } = {
  title: "The Golden Rules",
  html: "<p>If the text of this Rules Reference directly contradicts the text of the Learn to Play book, the text of the\n Rules Reference takes precedence.</p>\n <p>If the text of a card directly contradicts the text of either the Rules Reference or the Learn to Play book, the\n text of the card takes precedence.</p>",
};

